// Loads a client's newsletter.json (committed, generated by scripts/newsletter.mjs).
// Mirrors lib/data.ts. The newsletter is OPTIONAL: when the file is missing or the
// AI writer wasn't configured (status 'no-key'), the Newsletter tab still renders the
// real-data edition — it just omits the AI prose. Never fabricated.
import { useEffect, useState } from 'react';
import type { Newsletter } from '../types';

const CLIENT = (import.meta.env.VITE_CLIENT as string | undefined) || 'tybourne';

// Vite bundles every client's newsletter file (eager-optional: may not exist yet).
const loaders = import.meta.glob('../../clients/*/data/newsletter.json');

export type NewsletterState =
  | { status: 'loading' }
  | { status: 'absent' } // no newsletter.json at all — show real-data edition only
  | { status: 'ready'; data: Newsletter };

export function useNewsletter(): NewsletterState {
  const [state, setState] = useState<NewsletterState>({ status: 'loading' });

  useEffect(() => {
    let alive = true;
    const key = `../../clients/${CLIENT}/data/newsletter.json`;
    const loader = loaders[key];
    if (!loader) {
      setState({ status: 'absent' });
      return;
    }
    loader()
      .then((mod) => {
        if (!alive) return;
        const data = ((mod as { default?: Newsletter }).default ?? mod) as Newsletter;
        setState({ status: 'ready', data });
      })
      .catch(() => {
        if (!alive) return;
        setState({ status: 'absent' });
      });
    return () => {
      alive = false;
    };
  }, []);

  return state;
}
